# WAR ARENA - Deployment (server entry + env + Docker + health) - Installer
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-deploy.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Deployment installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/deploy/env.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "src/deploy/index.ts" "LyoqCiAqIFdBUiBkZXBsb3ltZW50IGxheWVyIOKAlCBlbnYsIHNlcnZlciBlbnRyeSwgYW5kIG9wcyB3aXJpbmcuCiAqIFRyYW5zcG9ydCArIGNvbmZpZ3VyYXRpb24gb25seTsgbm8gaW50ZWxsaWdlbmNlLCBubyBjb3JlIGltcG9ydHMuCiAqLwpleHBvcnQgKiBmcm9tICIuL2Vudi5qcyI7CmV4cG9ydCAqIGZyb20gIi4vc2VydmVyLmpzIjsK"
Write-B64 "tests/unit/deploy.test.ts" ""
Write-B64 "Dockerfile" ""
Write-B64 ".dockerignore" "bm9kZV9tb2R1bGVzCmRpc3QKLmdpdApfYmFja3VwLSoKKi5wczEKdGVzdHMKLmVudgo="
Write-B64 ".env.example" ""

# add start script to package.json (idempotent)
$pkg = Get-Content package.json -Raw | ConvertFrom-Json
if (-not $pkg.scripts.start){ $pkg.scripts | Add-Member -NotePropertyName start -NotePropertyValue "node dist/deploy/server.js" }
$enc = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText((Join-Path (Get-Location) "package.json"), (($pkg | ConvertTo-Json -Depth 30)), $enc)
Write-Host "  patched package.json start script (no BOM)" -ForegroundColor DarkGray

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Deployment installed. Expected: 910 passed + 1 skipped, 427 guards." -ForegroundColor Green
Write-Host "Run locally: npm run build; npm start   (GET /health -> 200)" -ForegroundColor Yellow
